"""dtssl.gui.replay: dataset browsing + whole-event free-run vs truth (Qt-free)."""
from __future__ import annotations

import numpy as np
import pytest

from dtssl.data.loader import body_velocity_series
from dtssl.data.schema import Segment
from dtssl.gui.replay import ReplaySession, horizons_from_config, list_datasets, list_events, list_labels
from dtssl.models import AnalyticFOPDTPlant, load_twin_params
from dtssl.paths import has_dataset


def _synthetic_segment(n: int = 240, ts: float = 1.0 / 60.0) -> Segment:
    """Truth generated by the official plant from rest (so the twin free-run must match it)."""
    params = load_twin_params()
    plant = AnalyticFOPDTPlant(params)
    t = np.arange(n) * ts
    cmd = np.column_stack([0.8 * np.sin(0.7 * t), 0.3 * np.cos(1.1 * t), 1.5 * np.sin(0.4 * t)])
    pose0 = (0.5, -0.25, 0.3)
    plant.reset(pose0)
    plant.prime_delay([])
    pos = np.empty((n, 3))
    pos[0] = pose0
    for k in range(1, n):
        pos[k] = plant.step(cmd[k - 1], ts)
    vbx, vby, vbw = body_velocity_series(t, pos[:, 0], pos[:, 1], pos[:, 2])
    dt = np.full(n, ts)
    return Segment(meta={"event": "synth_01", "label": "synth", "dataset": "synthetic", "robot_id": 4}, ts=ts,
                   t=t, dt=dt, cmd_vx=cmd[:, 0], cmd_vy=cmd[:, 1], cmd_w=cmd[:, 2],
                   pos_x=pos[:, 0], pos_y=pos[:, 1], theta=pos[:, 2],
                   vel_x_world=np.zeros(n), vel_y_world=np.zeros(n),
                   velb_x=vbx, velb_y=vby, velb_w=vbw, pose0=pose0, velb0=(0.0, 0.0, 0.0))


def test_horizons_from_config_matches_metrics_json():
    h = horizons_from_config()
    assert h == (6, 12, 24, 42, 60, 90)
    assert horizons_from_config({"horizons": [3, 9]}) == (3, 9)


def test_session_free_run_reproduces_truth_and_playhead_logic():
    seg = _synthetic_segment()
    s = ReplaySession.from_segment(seg, params=load_twin_params(), horizons=(6, 12, 24))
    assert s.n == seg.n and s.pose_sim.shape == (seg.n, 3) and s.epos.shape == (seg.n,)
    assert float(np.max(s.epos)) < 1e-9                       # same plant, same IC -> bit-identical
    assert s.epos_at_horizons() == {6: pytest.approx(0.0, abs=1e-9), 12: pytest.approx(0.0, abs=1e-9),
                                    24: pytest.approx(0.0, abs=1e-9)}
    assert s.horizon_times() == pytest.approx([0.1, 0.2, 0.4])
    assert s.velb_sim.shape == (seg.n, 3) and np.allclose(s.velb_sim, s.velb_truth)
    assert s.label == "synth" and s.event == "synth_01" and s.dataset == "synthetic"
    # ideal plant diverges from the FOPDT truth
    s.plant_kind = "ideal"
    s.recompute()
    assert float(np.max(s.epos)) > 1e-3
    # playhead
    assert s.seek(10) == 10 and s.sample()["i"] == 10 and s.sample()["t"] == pytest.approx(10 / 60)
    assert s.seek(-5) == 0 and s.seek(10_000) == s.n - 1
    s.seek(0)
    s.play()
    assert s.playing
    moved = s.advance(0.5)                                     # 0.5 s at 1x = 30 samples
    assert moved == 30 and s.index == 30
    s.set_speed(2.0)
    assert s.advance(0.5) == 60 and s.index == 90
    s.pause()
    assert s.advance(1.0) == 0
    s.play()
    s.advance(100.0)
    assert s.index == s.n - 1 and not s.playing               # stops at the end
    s.play()
    assert s.index == 0 and s.playing                          # play at the end restarts
    assert s.seek_time(1.0) == 60


@pytest.mark.requires_data
def test_dataset_browsing_and_real_event():
    ds = list_datasets()
    assert ds and ds[0] == "2026-05-18_19-2-15"
    labels = list_labels(ds[0])
    assert "side_to_side" in labels
    events = list_events(ds[0], "side_to_side")
    assert "side_to_side_01_05" in events
    s = ReplaySession.load("side_to_side", "side_to_side_01_05", dataset=ds[0])
    assert s.n > 100 and s.duration_s > 1.0
    eh = s.epos_at_horizons()
    assert set(eh) == set(horizons_from_config())
    assert all(0.0 <= v < 1.0 for v in eh.values())
    assert np.isfinite(s.epos).all() and np.isfinite(s.velb_sim).all()


def test_listing_without_dataset_is_empty(tmp_path):
    assert list_datasets(tmp_path) == []
    assert list_labels("x", tmp_path) == [] and list_events("x", "y", tmp_path) == []
    (tmp_path / "d1" / "splits" / "lab" / "ev_01").mkdir(parents=True)
    (tmp_path / "d1" / "splits" / "lab" / "ev_01" / "commands.parquet").write_bytes(b"")
    assert list_datasets(tmp_path) == ["d1"] and list_labels("d1", tmp_path) == ["lab"]
    assert list_events("d1", "lab", tmp_path) == ["ev_01"]


@pytest.mark.skipif(not has_dataset(), reason="dataset absent")
def test_default_root_lists_canonical_first():
    assert list_datasets()[0] == "2026-05-18_19-2-15"
